// barbLib offline support and updates.
//
// Each release is cached as ONE complete set (list in precache.json, generated by
// tools/release.py) and the app is served from that set, so old and new files can
// never mix, and barbLib opens instantly, online or offline.
//
// Updating: a new release changes this file, so the browser installs the new
// worker in the background and it waits. The app then shows "Update now" (which
// tells it to take over and reloads), or the update happens on the next launch.
//
// On localhost (development) files always come from the network.
// Books themselves live in IndexedDB, not here.
const CACHE = 'barblib-1.0.7'
const DEV = ['localhost', '127.0.0.1'].includes(location.hostname)
const FALLBACK_SHELL = ['./', 'index.html', 'css/app.css', 'manifest.webmanifest', 'js/app.js']

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE)
    let list = FALLBACK_SHELL
    try { list = await (await fetch('precache.json', { cache: 'no-cache' })).json() } catch { /* use fallback */ }
    // all-or-nothing: an incomplete set must never become the active version
    await cache.addAll(list.map(u => new Request(u, { cache: 'no-cache' })))
  })())
})

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('barblib-') || k.startsWith('reader-'))
      .filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()))
})

self.addEventListener('message', e => {
  if (e.data === 'skipWaiting') self.skipWaiting()
  if (e.data === 'version') e.ports[0]?.postMessage(CACHE)
})

self.addEventListener('fetch', e => {
  const { request } = e
  const url = new URL(request.url)
  if (request.method !== 'GET' || url.origin !== location.origin) return
  if (url.pathname.includes('/samples/') || url.pathname.endsWith('/version.json')) return

  e.respondWith((async () => {
    const cache = await caches.open(CACHE)
    const fromCache = async () => await cache.match(request, { ignoreSearch: true })
      ?? (request.mode === 'navigate' ? await cache.match('./') ?? await cache.match('index.html') : undefined)

    if (DEV) {
      try { return await fetch(request, { cache: 'no-cache' }) }
      catch { return (await fromCache()) ?? Response.error() }
    }

    const cached = await fromCache()
    if (cached) return cached
    // not part of the release set (e.g. rare PDF font tables): fetch once, keep it
    const res = await fetch(request)
    if (res.ok) cache.put(request, res.clone())
    return res
  })())
})
